package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The people kept on a sheet, in the order they were added. A name is stored without surrounding
 * spaces and is unique on its sheet regardless of case. An edit is made from a version of the
 * person; once someone else has saved the person since, it is refused.
 */
@Service
public class PersonService {

    private static final int MAX_NAME = 100;
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
            throw nameInUse();
        }
        Person person = people.save(new Person(sheetId, trimmed, grade));
        audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
        return person;
    }

    /** A line of an import that breaks a rule: its number (from 1) and why. */
    public record ImportError(int line, String message) {
    }

    /** How many people an import added, or the lines that stopped it (then nothing is added). */
    public record ImportResult(int added, List<ImportError> errors) {
    }

    /**
     * Import people from lines of name,grade. Every line is checked first with the rules of the form;
     * a name repeated in the paste is compared like uniqueness on the sheet. If any line breaks a
     * rule nothing is added; otherwise each person is added in order. Blank lines are skipped.
     */
    @Transactional
    public ImportResult importPeople(String sheetId, String user, String text) {
        String[] lines = text.split("\\r?\\n", -1);
        List<ImportError> errors = new ArrayList<>();
        List<String[]> rows = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.isBlank()) {
                continue;
            }
            int number = i + 1;
            int comma = line.lastIndexOf(',');
            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
            String error = null;
            if (name.isEmpty()) {
                error = "Enter a name.";
            } else if (name.length() > MAX_NAME) {
                error = "The name is too long.";
            } else if (!GRADES.contains(grade)) {
                error = "The grade must be A, B or C.";
            } else if (people.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
                error = "That name is already in use on this sheet.";
            } else if (!seen.add(name.toLowerCase(Locale.ROOT))) {
                error = "That name is repeated in the import.";
            }
            if (error != null) {
                errors.add(new ImportError(number, error));
            } else {
                rows.add(new String[] {name, grade});
            }
        }
        if (!errors.isEmpty()) {
            return new ImportResult(0, errors);
        }
        if (!rows.isEmpty()) {
            sheets.load(sheetId, user);
        }
        for (String[] row : rows) {
            Person person = people.save(new Person(sheetId, row[0], row[1]));
            audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
        }
        return new ImportResult(rows.size(), List.of());
    }

    @Transactional
    public Person update(String sheetId, String user, Long personId, long version, String name, String grade) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getVersion() != version) {
            throw changedMeanwhile();
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
            throw nameInUse();
        }
        person.setName(trimmed);
        person.setGrade(grade);
        try {
            person = people.saveAndFlush(person);
        } catch (OptimisticLockingFailureException e) {
            throw changedMeanwhile();
        }
        audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + person.getGrade());
        return person;
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Person changed since it was loaded");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
    }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

export interface Person {
  id: number;
  name: string;
  grade: Grade;
  /** Raised each time the person is saved; an edit sends back the version it was made from. */
  version: number;
}

export interface PersonFields {
  name: string;
  grade: Grade;
}

/** What an import did: how many it added, or the lines (numbered from 1) that stopped it. */
export interface ImportResult {
  added: number;
  errors: { line: number; message: string }[];
}

// The people kept on the active sheet, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class PeopleApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(): Promise<Person[]> {
    return firstValueFrom(this.http.get<Person[]>(this.url(), { headers: this.headers() }));
  }

  add(fields: PersonFields): Promise<Person> {
    return firstValueFrom(this.http.post<Person>(this.url(), fields, { headers: this.headers() }));
  }

  /** Add people from pasted lines of name,grade; all of them, or none when any line is bad. */
  importLines(text: string): Promise<ImportResult> {
    return firstValueFrom(
      this.http.post<ImportResult>(`${this.url()}/import`, { text }, { headers: this.headers() }),
    );
  }

  /** Refused with 412 when someone else has saved the person since this version was read. */
  update(id: number, version: number, fields: PersonFields): Promise<Person> {
    return firstValueFrom(
      this.http.put<Person>(`${this.url()}/${id}`, { ...fields, version }, { headers: this.headers() }),
    );
  }

  private url(): string {
    const id = this.session.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return `/api/sheets/${encodeURIComponent(id)}/people`;
  }

  private headers(): Record<string, string> {
    const user = this.session.user();
    if (!user) throw new Error('not signed in');
    return { 'X-User': user };
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, effect, inject, signal, untracked } from '@angular/core';
import { Claims, counts, formatCents } from '../../core/claims';
import { GRADES, Grade, ImportResult, PeopleApi, Person } from '../../core/people';
import { Rates } from '../../core/rates';
import { Session } from '../../core/session';
import { PersonClaims } from '../claims/claims';

// The sheet's people, in the order they were added, and the one form that adds a person or edits
// an existing one.
@Component({
  selector: 'app-people',
  imports: [PersonClaims],
  template: `
    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>

      <form (submit)="save($event)">
        <label for="person-name">Name</label>
        <input
          id="person-name"
          data-testid="person-form-name"
          [value]="name()"
          (input)="name.set($any($event.target).value); error.set(null)"
        />
        <label for="person-grade">Grade</label>
        <select
          id="person-grade"
          data-testid="person-form-grade"
          [value]="grade()"
          (change)="grade.set($any($event.target).value); error.set(null)"
        >
          @for (g of grades; track g) {
            <option [value]="g" [selected]="g === grade()">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="person-form-submit">
          {{ editingId() === null ? 'Add person' : 'Save person' }}
        </button>
        @if (editingId() !== null) {
          <button type="button" data-testid="person-form-cancel" (click)="reset()">Cancel</button>
        }
        @if (error(); as err) {
          <p role="alert" data-testid="person-form-error">{{ err }}</p>
        }
      </form>

      <form (submit)="importPeople($event)">
        <label for="import-text">Import people (one name,grade per line)</label>
        <textarea
          id="import-text"
          data-testid="import-text"
          rows="4"
          [value]="importText()"
          (input)="importText.set($any($event.target).value); importResult.set(null); importError.set(null)"
        ></textarea>
        <button type="submit" data-testid="import-submit">Import</button>
        @if (importResult(); as result) {
          <div role="status">
            <p>Added <strong data-testid="import-added">{{ result.added }}</strong></p>
            @if (result.errors.length > 0) {
              <p>Nothing was imported; fix these lines:</p>
              <ul>
                @for (e of result.errors; track e.line) {
                  <li [attr.data-testid]="'import-error-' + e.line">Line {{ e.line }}: {{ e.message }}</li>
                }
              </ul>
            }
          </div>
        }
        @if (importError(); as err) {
          <p role="alert" data-testid="import-error">{{ err }}</p>
        }
      </form>

      <table>
        <thead>
          <tr><th scope="col">Name</th><th scope="col">Grade</th><th scope="col">Claimed</th><th scope="col">Due</th><th scope="col">Claims</th><th scope="col"><span class="visually-hidden">Actions</span></th></tr>
        </thead>
        <tbody>
          @for (p of people(); track p.id) {
            <tr [attr.data-testid]="'person-row-' + p.id">
              <td data-testid="person-name">{{ p.name }}</td>
              <td data-testid="person-grade">{{ p.grade }}</td>
              <td data-testid="person-claimed">{{ claimed(p.id) }}</td>
              <td data-testid="person-due-total">{{ dueTotal(p) }}</td>
              <td><app-person-claims [personId]="p.id" [personName]="p.name" [grade]="p.grade" /></td>
              <td>
                <button type="button" [attr.data-testid]="'person-edit-' + p.id" (click)="edit(p)">
                  Edit<span class="visually-hidden"> {{ p.name }}</span>
                </button>
              </td>
            </tr>
          }
        </tbody>
      </table>

      <p>Claimed total <strong data-testid="rollup-claimed-total">{{ claimedTotal() }}</strong></p>
      <p>Due total <strong data-testid="rollup-due-total">{{ dueTotalAll() }}</strong></p>
    </section>
  `,
})
export class People {
  private readonly api = inject(PeopleApi);
  private readonly session = inject(Session);
  private readonly claims = inject(Claims);
  private readonly rates = inject(Rates);

  protected readonly grades = GRADES;
  protected readonly people = signal<Person[]>([]);
  protected readonly name = signal('');
  protected readonly grade = signal<Grade>('A');
  protected readonly editingId = signal<number | null>(null);
  /** The version of the person the editor loaded. */
  private editingVersion = 0;
  /** Set while a submit awaits the store, so a second submit does not store a second record. */
  private saving = false;
  protected readonly error = signal<string | null>(null);
  protected readonly importText = signal('');
  protected readonly importResult = signal<ImportResult | null>(null);
  protected readonly importError = signal<string | null>(null);
  /** Set while an import awaits the store, so a second submit does not import twice. */
  private importing = false;
  protected readonly claimedTotal = computed(() => formatCents(this.claims.totalCents()));

  /**
   * Each person's due-total in cents, by person id: the sum of their counted claims' due figures as
   * shown (each already rounded), skipping those that are n/a. Absent when none has a figure and
   * their grade has no rate today.
   */
  private readonly dueCents = computed(() => {
    const out = new Map<number, number>();
    for (const p of this.people()) {
      const figures = this.claims
        .all()
        .filter((c) => c.personId === p.id && counts(c))
        .map((c) => this.rates.dueOf(c, p.grade))
        .filter((c) => c !== undefined);
      if (figures.length > 0 || this.rates.byGrade().has(p.grade)) {
        out.set(p.id, figures.reduce((sum, c) => sum + c, 0));
      }
    }
    return out;
  });

  /** Everyone's due-total added up, skipping those that are n/a. */
  protected readonly dueTotalAll = computed(() =>
    formatCents([...this.dueCents().values()].reduce((sum, c) => sum + c, 0)),
  );

  constructor() {
    // Re-read the store each time the sheet is (re-)loaded.
    effect(() => {
      this.session.loads();
      untracked(() => {
        this.reset();
        this.importText.set('');
        this.importResult.set(null);
        this.importError.set(null);
        void this.reload();
        void this.claims.reload();
      });
    });
  }

  protected claimed(personId: number): string {
    return formatCents(this.claims.claimedCents().get(personId) ?? 0);
  }

  protected dueTotal(person: Person): string {
    const cents = this.dueCents().get(person.id);
    return cents === undefined ? 'n/a' : formatCents(cents);
  }

  protected edit(person: Person): void {
    this.editingId.set(person.id);
    this.editingVersion = person.version;
    this.name.set(person.name);
    this.grade.set(person.grade);
    this.error.set(null);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.name.set('');
    this.grade.set('A');
    this.error.set(null);
  }

  protected async save(event: Event): Promise<void> {
    event.preventDefault();
    if (this.saving) return;
    this.error.set(null);
    const fields = { name: this.name(), grade: this.grade() };
    if (!fields.name.trim()) {
      this.error.set('Enter a name.');
      return;
    }
    const id = this.editingId();
    this.saving = true;
    try {
      if (id === null) {
        const added = await this.api.add(fields);
        this.people.update((list) => [...list, added]);
      } else {
        const saved = await this.api.update(id, this.editingVersion, fields);
        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
      }
      this.reset();
    } catch (e) {
      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
        await this.showCurrent(id);
        this.error.set('Someone else saved this person since you opened it. Their values are shown; open it again to edit.');
        return;
      }
      if (e instanceof HttpErrorResponse && e.status === 409) {
        this.error.set('That name is already in use on this sheet.');
        return;
      }
      this.error.set(id === null ? 'The person could not be added.' : 'The person could not be saved.');
    } finally {
      this.saving = false;
    }
  }

  protected async importPeople(event: Event): Promise<void> {
    event.preventDefault();
    if (this.importing) return;
    this.importResult.set(null);
    this.importError.set(null);
    this.importing = true;
    try {
      const result = await this.api.importLines(this.importText());
      this.importResult.set(result);
      if (result.added > 0) {
        this.importText.set('');
        await this.reload();
      }
    } catch {
      this.importError.set('The people could not be imported.');
    } finally {
      this.importing = false;
    }
  }

  /** Re-read the store and show the person's current values in the form and in their row. */
  private async showCurrent(id: number): Promise<void> {
    await this.reload();
    const current = this.people().find((p) => p.id === id);
    if (current) {
      this.name.set(current.name);
      this.grade.set(current.grade);
    }
  }

  private async reload(): Promise<void> {
    try {
      this.people.set(await this.api.list());
    } catch {
      this.people.set([]);
    }
  }
}

